//! Offline numerical oracle generated by executing isolated original ARM64
//! arithmetic (Big Sur 11.7.2 / Dock 2092.50.2), not a macOS runtime benchmark.
//! The 132 Genie cases have gap=0; nonzero-gap behavior has separate tests.

use clarion_motion::genie::GeniePhases;
use clarion_motion::workspace_feedback::FeedbackState;

#[test]
fn matches_372_original_arm64_instruction_samples() {
    let mut count = [0usize; 2];
    for line in include_str!("fixtures/big-sur-arm64.csv").lines().skip(1) {
        let (kind, values) = line.split_once(',').unwrap();
        let n: Vec<f64> = values
            .split(',')
            .map(|s| if s.is_empty() { 0. } else { s.parse().unwrap() })
            .collect();
        if kind == "velocity" {
            let mut state = FeedbackState {
                position: n[0],
                velocity: n[1],
                start: n[2],
                target: n[3],
                single_pixel: n[4],
                allow_bounce: n[5] != 0.,
            };
            let mut done = false;
            for _ in 0..n[6] as usize {
                if state.step_60hz() {
                    done = true;
                    break;
                }
            }
            assert!(
                (state.position - n[7]).abs() < 1e-12,
                "position: {line} {state:?}"
            );
            assert!(
                (state.velocity - n[8]).abs() < 1e-12,
                "velocity: {line} {state:?}"
            );
            assert_eq!(done, n[9] != 0., "{line}");
            count[0] += 1;
        } else {
            assert_eq!(kind, "phase");
            let phases = GeniePhases::new(n[0], n[1], n[2], n[3], n[4]).unwrap();
            let (cross, travel) = phases.sample(n[5]);
            assert!((cross - n[7]).abs() < 1e-12, "cross: {line} {cross}");
            assert!((travel - n[8]).abs() < 1e-12, "travel: {line} {travel}");
            count[1] += 1;
        }
    }
    assert_eq!(count, [240, 132]);
}
